package com.bank.disagree;

import com.bank.disagree.model.Proposal;
import com.bank.disagree.service.DisagreementResolver;
import java.util.logging.*;

// Runnable demo: resolve a design disagreement with evidence, then disagree-and-commit.
public class DisagreementDemo {
    private static final Logger log = Logger.getLogger("Disagree");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // Two proposals, each with a MEASURED p99 latency at 2x peak load (evidence).
        Proposal sync = new Proposal("Priya", "Synchronous transfer",
            2200, "Simpler code, but p99 breaches SLA at 2x load");
        Proposal async = new Proposal("Rajesh", "Asynchronous transfer",
            350, "More moving parts, but holds p99 under SLA at 2x load");

        DisagreementResolver resolver = new DisagreementResolver(log);
        resolver.resolve(sync, async);
    }
}
