package com.bank.disagree.model;

// A design proposal with the person, the idea, and MEASURED evidence (not opinion).
public class Proposal {
    private final String author;
    private final String design;
    private final int measuredP99Ms;   // evidence: measured p99 at 2x load
    private final String note;

    public Proposal(String author, String design, int measuredP99Ms, String note) {
        this.author = author;
        this.design = design;
        this.measuredP99Ms = measuredP99Ms;
        this.note = note;
    }

    public String getAuthor() { return author; }
    public String getDesign() { return design; }
    public int getMeasuredP99Ms() { return measuredP99Ms; }
    public String getNote() { return note; }
}
